package com.trough.hot;
import android.os.*;import java.io.*;import org.json.*;
/** Bounded opposing-instance activation, physical swing and inverse movement check. */
final class HalfSwordFacingCheck implements Runnable {
 final HalfSwordView v;final HalfSwordAimCheck input;final Handler ui=new Handler(Looper.getMainLooper());final long began=SystemClock.uptimeMillis();int stage,steps;boolean complete;double startX,startDistance,endDistance,handX,handY,handZ,peak;JSONObject standing;
 HalfSwordFacingCheck(HalfSwordView view){v=view;input=new HalfSwordAimCheck(v);}void start(){ui.postDelayed(this,150);}void need(boolean b,String s)throws Exception{if(!b)throw new Exception(s);}
 double distance()throws Exception{JSONArray p=input.observation().getJSONArray("pelvis_cm");return Math.hypot(v.opponentRootX-p.getDouble(0),v.opponentRootY-p.getDouble(1));}
 public void run(){try{need(SystemClock.uptimeMillis()-began<25000,"Facing timeout");need(v.renderVisible&&!v.characterFailed,"Scene unavailable");switch(stage){
 case 0:if(v.characterRunning)input.click("Run / pause");if(v.opponentFollow)input.click("Opponent spacing · prototype");input.click("Duel setup");need(v.opponentFacingRequested&&v.characterStanceSupport&&!v.characterRunning&&v.characterPending==0,"Duel setup must select opposing stance and stay paused");stage=1;break;
 case 1:if(v.resetPending())break;input.click("Run / pause");steps=v.characterSteps;stage=2;break;
 case 2:if(v.characterSteps-steps<60)break;need(v.opponentFacingApplied&&v.passiveActive,"Opposing instance not applied");standing=input.observation();JSONArray p=standing.getJSONArray("pelvis_cm"),h=standing.getJSONArray("right_hand_cm");need(v.opponentRootX<p.getDouble(0)-100&&h.getDouble(0)<p.getDouble(0)-30&&v.opponentHandX>v.opponentRootX+30,"Weapons do not face each other");need(v.opponentRootZ>70&&p.getDouble(2)>70,"Facing actors not standing");need(Math.abs(v.followX-(p.getDouble(0)+v.opponentRootX)*.005)<.03&&Math.abs(v.followZ-(p.getDouble(1)+v.opponentRootY)*.005)<.03,"Duel camera not following both roots");startX=v.opponentRootX;startDistance=distance();input.click("Opponent spacing · prototype");steps=v.characterSteps;stage=3;break;
 case 3:if(v.characterSteps-steps<180)break;endDistance=distance();need(v.opponentRootX>startX+10&&endDistance<startDistance-10&&endDistance>95,"Turned spacing inverse mapping failed");input.click("Opponent spacing · prototype");handX=v.opponentHandX;handY=v.opponentHandY;handZ=v.opponentHandZ;input.click("Opponent swing");steps=v.characterSteps;stage=4;break;
 case 4:peak=Math.max(peak,Math.sqrt(Math.pow(v.opponentHandX-handX,2)+Math.pow(v.opponentHandY-handY,2)+Math.pow(v.opponentHandZ-handZ,2)));if(v.characterSteps-steps<180)break;need(peak>10&&!v.opponentSwingActive&&v.opponentRootZ>70,"Turned physical swing failed");need(v.opponentBladeAvailable&&v.opponentBladeProbes>200,"Turned blade queries absent");input.click("Run / pause");input.pausedSteps=-1;stage=5;break;
 case 5:if(!input.pausedScene(true))break;{File base=new File(v.getContext().getFilesDir(),"home/.trough");try(FileInputStream in=new FileInputStream(new File(base,"half-sword-aim-held.png"));FileOutputStream out=new FileOutputStream(new File(base,"half-sword-opposing-held.png"))){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))>0)out.write(bytes,0,n);}}complete=true;finish(null);return;
 }ui.postDelayed(this,50);}catch(Throwable e){v.characterRunning=false;v.opponentFollow=false;v.cancelAllTouchInputs();v.refreshRunControl();finish(e.toString());}}
 void finish(String error){try{JSONObject o=new JSONObject().put("passed",complete&&error==null).put("error",error==null?"":error).put("stage",stage).put("facing_applied",v.opponentFacingApplied).put("start_distance_cm",startDistance).put("end_distance_cm",endDistance).put("opponent_swing_motion_cm",peak).put("standing_observation",standing==null?JSONObject.NULL:standing).put("steps",v.characterSteps).put("opponent_root_z_cm",v.opponentRootZ).put("module",HalfSwordBridge.loadedModuleSha256).put("performance",v.performance()).put("time_ms",System.currentTimeMillis()).put("scope","Actual opposing pose, physical swing, inverse spacing and blade query activation; not contact force/damage/duel AI acceptance");Payloads.writeSmall(new File(v.getContext().getFilesDir(),"home/.trough/half-sword-facing-check-result.json"),o.toString());}catch(Exception ignored){}}
}
